WITH event_type_budget AS (SELECT e.type, COALESCE(SUM(b.spent), 0) as total_spent, COALESCE(SUM(b.remaining), 0) as total_remaining FROM budget b INNER JOIN event e ON b.link_to_event = e.event_id GROUP BY e.type) SELECT type, total_spent, total_remaining, ROUND((total_spent::numeric / NULLIF((total_spent + total_remaining)::numeric, 0)) * 100, 2) as utilization_pct FROM event_type_budget ORDER BY total_spent DESC LIMIT 10;
